-- Reviewed additive seed, run serially in system DB. No role grants.
BEGIN;
SET @member_root=(SELECT menu_id FROM sys_menu WHERE parent_id=0 AND path='member' AND menu_type='M' ORDER BY menu_id LIMIT 1);
SET @member_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@member_root AND path='user' AND menu_type='C' ORDER BY menu_id LIMIT 1);
SET @member_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@member_root AND path='level' AND menu_type='C' ORDER BY menu_id LIMIT 1);
SET @member_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@member_root AND path='group' AND menu_type='C' ORDER BY menu_id LIMIT 1);
SET @member_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@member_root AND path='tag' AND menu_type='C' ORDER BY menu_id LIMIT 1);
SET @member_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@member_root AND path='record' AND menu_type='C' ORDER BY menu_id LIMIT 1);
SET @member_page=(SELECT menu_id FROM sys_menu WHERE parent_id=@member_root AND path='config' AND menu_type='C' ORDER BY menu_id LIMIT 1);
COMMIT;
